package io.github.diodeme.ji.host;

import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.StandardCopyOption;
import java.nio.file.StandardOpenOption;
import java.time.Duration;
import java.time.Instant;
import java.util.ArrayList;
import java.util.List;
import java.util.Map;
import java.util.Set;

/** Bounded structured NDJSON audit/diagnostic log with atomic retention compaction. */
public final class RetentionLog {
    private static final Set<String> ALLOWED_FIELDS = Set.of(
            "hostId", "workspaceId", "sessionId", "operationId", "clientId", "deviceId",
            "permissionId", "tool", "ruleId", "provider", "status", "code", "traceId");
    private final Path path;
    private final Duration retention;
    private final int maximumEntries;
    private final List<Entry> entries = new ArrayList<>();

    public RetentionLog(Path path, Duration retention, int maximumEntries) {
        if (path == null || retention == null || retention.isNegative() || maximumEntries < 1) {
            throw new IllegalArgumentException("invalid retained log configuration");
        }
        this.path = path.toAbsolutePath().normalize();
        this.retention = retention;
        this.maximumEntries = maximumEntries;
    }

    public synchronized void append(Entry entry) {
        var safe = new java.util.TreeMap<String, String>();
        entry.fields().forEach((key, value) -> {
            if (ALLOWED_FIELDS.contains(key) && value != null && !value.isBlank()
                    && value.length() <= 256 && value.chars().noneMatch(Character::isISOControl)) {
                safe.put(key, value);
            }
        });
        entries.add(new Entry(entry.id(), entry.occurredAt(), entry.type(), safe));
        if (entries.size() > maximumEntries) entries.subList(0, entries.size() - maximumEntries).clear();
        persist();
    }

    public synchronized int purge(Instant now) {
        Instant oldest = now.minus(retention);
        int before = entries.size();
        entries.removeIf(entry -> entry.occurredAt().isBefore(oldest));
        if (entries.size() != before) persist();
        return before - entries.size();
    }

    public synchronized List<Entry> entries() { return List.copyOf(entries); }

    private void persist() {
        try {
            Path parent = path.getParent();
            if (parent == null) throw new IOException("retained log has no parent");
            Files.createDirectories(parent);
            Path temporary = Files.createTempFile(parent, ".retention-", ".tmp");
            try {
                var body = new StringBuilder();
                for (Entry entry : entries) {
                    body.append('{').append("\"id\":\"").append(escape(entry.id()))
                            .append("\",\"occurredAt\":\"").append(entry.occurredAt())
                            .append("\",\"type\":\"").append(escape(entry.type())).append("\",\"fields\":{");
                    boolean first = true;
                    for (var field : entry.fields().entrySet()) {
                        if (!first) body.append(',');
                        first = false;
                        body.append('"').append(escape(field.getKey())).append("\":\"")
                                .append(escape(field.getValue())).append('"');
                    }
                    body.append("}}\n");
                }
                Files.writeString(temporary, body, StandardCharsets.UTF_8, StandardOpenOption.TRUNCATE_EXISTING);
                try {
                    Files.move(temporary, path, StandardCopyOption.REPLACE_EXISTING, StandardCopyOption.ATOMIC_MOVE);
                } catch (java.nio.file.AtomicMoveNotSupportedException unsupported) {
                    Files.move(temporary, path, StandardCopyOption.REPLACE_EXISTING);
                }
            } finally {
                Files.deleteIfExists(temporary);
            }
        } catch (IOException failure) {
            throw new IllegalStateException("retained log is unavailable", failure);
        }
    }

    private static String escape(String value) {
        return value.replace("\\", "\\\\").replace("\"", "\\\"");
    }

    public record Entry(String id, Instant occurredAt, String type, Map<String, String> fields) {
        public Entry {
            if (id == null || id.isBlank() || occurredAt == null || type == null || type.isBlank() || fields == null) {
                throw new IllegalArgumentException("invalid retained log entry");
            }
            fields = Map.copyOf(fields);
        }
    }
}
